// Generated by `npm run models` (tools/3d/compress.sh). Do not edit by hand.
// Content hashes of public/models/*.glb: they version the URLs, because the models are
// served with an immutable cache header and a rebuild keeps the same filenames.

const HASHES: Record<string, string> = {
  'pyoor-herbal-black-salt.glb': '95ba130c1e',
  'pyoor-jar-pink-rock-salt.glb': '270ea54f07',
  'pyoor-natural-lake-salt.glb': 'eeed386136',
  'pyoor-pouch-herbal-black-salt.glb': 'ccba76bb0a',
  'pyoor-pouch-natural-lake-salt.glb': '253396e08d',
  'pyoor-pouch-pink-rock-salt.glb': 'f3581f71a0',
};

/** URL for a compressed jar in public/models, versioned by its content. */
export function modelUrl(file: string): string {
  const hash = HASHES[file];
  if (!hash) throw new Error(`Unknown model "${file}": run npm run models`);
  return `/models/${file}?v=${hash}`;
}
